<template><SuperAdminLayout><main class="page"><header><h1>7.1 Emergency Shutdown</h1><RouterLink to="/super-admin/dashboard">← Back to Main</RouterLink></header><p v-if="notice" :class="['notice',error?'error':'']">{{notice}}</p><section><h2>Shutdown Control</h2><form @submit.prevent="submit"><fieldset><legend>Shutdown Scope</legend><label v-for="x in scopes" :key="x.value"><input v-model="f.scope" type="radio" :value="x.value"> {{x.label}}</label></fieldset><label>Shutdown Reason<select v-model="f.reason"><option>Security Review</option><option>System Maintenance</option><option>Security Risk</option><option>Emergency Test</option></select></label><label>Security Risk Level<select v-model="f.risk"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label><label>Shutdown Date<input v-model="f.startDate" type="date"></label><label>Shutdown Time<input v-model="f.startTime" type="time"></label><label :class="{dim:!customerScope}">Customer Account No.<input v-model="f.customer" :disabled="!customerScope" placeholder="Enter Account No."></label><label :class="{dim:!customerScope}">Customer Name<input :disabled="!customerScope" placeholder="Enter Customer Name"></label><label>Expected Restore Date<input v-model="f.endDate" type="date" required></label><label>Expected Restore Time<input v-model="f.endTime" type="time" required></label><label>Shutdown Requested By<input :value="userName" readonly></label><label>Approved By<input value="Super Admin" readonly></label><label>Administrator Password<input v-model="f.password" type="password" required></label><label>Security PIN<input v-model="f.pin" type="password"></label><div class="actions"><button class="danger">⚠ EMERGENCY SHUT DOWN</button><button type="button" @click="reset">Cancel</button></div></form></section></main></SuperAdminLayout></template>
<script setup>import{computed,reactive,ref}from'vue';import{RouterLink}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const d=new Date(),today=d.toISOString().slice(0,10),time=d.toTimeString().slice(0,5),notice=ref(''),error=ref(false),userName=computed(()=>authState.user?.name||'System Admin'),scopes=[{value:'one_customer',label:'One Customer Account'},{value:'selected_customers',label:'Selected Customers'},{value:'all_customers',label:'All Customer Accounts'},{value:'entire_platform',label:'Entire Platform'}],f=reactive({scope:'entire_platform',customer:'',reason:'Security Review',risk:'high',startDate:today,startTime:time,endDate:today,endTime:'16:00',password:'',pin:''}),customerScope=computed(()=>['one_customer','selected_customers'].includes(f.scope));function reset(){Object.assign(f,{scope:'entire_platform',customer:'',reason:'Security Review',risk:'high',startDate:today,startTime:time,endDate:today,endTime:'16:00',password:'',pin:''})}async function submit(){if(customerScope.value&&!f.customer){error.value=true;notice.value='Enter a customer account number for this shutdown scope.';return}try{await client.post('/super-admin/emergency-shutdowns',{scope:f.scope,customer_id:customerScope.value?f.customer:null,reason:f.reason,risk_level:f.risk,expected_restore_at:`${f.endDate}T${f.endTime}`,message:`Shutdown scheduled from ${f.startDate} ${f.startTime}.`,password:f.password});error.value=false;notice.value='Emergency shutdown has been recorded and is now active.';reset()}catch(e){error.value=true;notice.value=e.response?.data?.message||'Unable to record the shutdown.'}}</script>
<style scoped>.page{color:#071541}.page>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page h1{margin:0;font-size:2rem}.page>header a,button{border:1px solid #cbd8eb;border-radius:5px;background:#fff;padding:10px 18px;color:#071541;font:700 .75rem inherit;text-decoration:none;cursor:pointer}.notice{padding:11px 14px;border:1px solid #a4d4b0;background:#effaf1;color:#17632d;border-radius:6px}.notice.error{border-color:#ffc1c1;background:#fff2f2;color:#b20d0d}section{padding:16px;border:1px solid #dbe4ef;border-radius:7px;background:#fff}h2{margin:0 0 14px;padding-bottom:11px;border-bottom:1px solid #dbe4ef;color:#ed1010;font-size:1rem}form{display:grid;grid-template-columns:1.15fr repeat(4,minmax(130px,1fr));gap:14px 23px}label,fieldset{display:grid;gap:6px;min-width:0;border:0;padding:0;font-size:.69rem;font-weight:800}legend{margin-bottom:8px;font-size:.69rem;font-weight:800}fieldset{grid-row:span 2}fieldset label{display:flex;gap:7px;margin-bottom:7px;font-size:.75rem;font-weight:500}input,select{box-sizing:border-box;width:100%;height:36px;border:1px solid #cad8ed;border-radius:5px;padding:0 10px;font:500 .77rem inherit}.dim{opacity:.55}.actions{grid-column:4/-1;display:grid;grid-template-columns:1fr 1fr;gap:12px}.danger{background:#e10b0b;border-color:#e10b0b;color:#fff}@media(max-width:1000px){form{grid-template-columns:repeat(3,1fr)}fieldset{grid-row:auto;grid-column:1/-1;display:flex;gap:15px;flex-wrap:wrap}.actions{grid-column:2/-1}}@media(max-width:600px){.page>header{display:block}.page>header a{display:inline-block;margin-top:12px}form{grid-template-columns:1fr}.actions{grid-column:auto}}</style>
